ize:17px;max-width:38ch;margin-top:16px}.intro h1 span{display:inline}h1{max-width:9ch}.exhibit{grid-template-columns:1fr;gap:10px}.board-frame{padding:8px;border-radius:16px}.board{gap:3px}.puck{width:calc((100% - 18px)/7);height:calc((100% - 18px)/7)}.board-top{margin-bottom:12px;gap:12px}.progress{gap:5px}.progress span{width:26px;height:26px;font-size:12px}.board-top h2{font-size:25px}.board-top p{font-size:13px}.board-bottom{font-size:13px}.cell{border-radius:4px}.cell.goal{font-size:10px}.cell.goal:after{border-width:1px}.feedback{min-height:75px;padding-top:14px}.control-title{font-size:16px;margin-bottom:10px}.controls{display:grid;grid-template-columns:minmax(160px,1.35fr) minmax(0,1fr);gap:12px;align-items:center}.pad{width:100%;max-width:280px;gap:6px}.pad button{min-height:57px}.tools{display:grid;gap:7px;margin:0}.tools button{min-height:46px}.tip{margin-bottom:0}.invention{display:grid;grid-template-columns:42% 1fr;gap:18px}.invention img{margin:0}.invention h3{font-size:23px}.invention p{font-size:14px}.rules{grid-template-columns:1fr;gap:20px;margin-top:28px}.rules p{font-size:16px}.legend{gap:5px}nav span{font-size:12px}}@media(prefers-reduced-motion:reduce){.puck{transition:none}button:active:not(:disabled){transform:none}}
