<body>
<header><nav aria-label="Page"><a href="./">Chloe Reads Jon</a><span>A CD case. A mouse. A small detour.</span></nav><div class="intro"><h1>GlassMouse <span>Glide.</span></h1><p>One nudge. No brakes.<br>Slide the homemade mouse into the yellow dock.</p></div></header>
<main>
<div class="exhibit">
<section class="game" aria-labelledby="level-title">
<div class="board-top"><div><h2 id="level-title" tabindex="-1">First slide</h2><p id="objective">Board 1 of 3 · Stop on the dock. Passing over it doesn't count.</p></div><div class="progress" aria-label="Board progress"><span class="current" aria-current="step">1</span><span>2</span><span>3</span></div></div>
<div class="board-frame"><div id="board" class="board" role="group" tabindex="0" aria-label="Sliding puzzle" aria-describedby="how-to board-state"></div></div>
<div class="board-bottom"><span class="legend"><i aria-hidden="true"></i> Yellow = dock · dark = blocker</span><span id="moves" class="moves">0 moves</span></div>
<p class="sr-only" id="board-state"></p>
<div class="feedback"><div id="success" hidden><h3 id="success-title" tabindex="-1">Docked!</h3></div><p id="message" role="status" aria-live="polite" aria-atomic="true">Take a nudge. The mouse stops at the next blocker or edge.</p><button id="next" class="next" hidden>Next board</button></div>
</section>
<aside aria-label="Game controls and invention">
<p class="control-title">Give it a nudge</p>
<div class="controls"><div class="pad" aria-label="Direction controls">
<button class="up" data-dir="up" aria-label="Slide up"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><path d="M12 21V3M4 11l8-8 8 8"/></svg>Up</button>
<button class="left" data-dir="left" aria-label="Slide left"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><path d="M21 12H3m8-8-8 8 8 8"/></svg>Left</button>
<button class="down" data-dir="down" aria-label="Slide down"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><path d="M12 3v18m-8-8 8 8 8-8"/></svg>Down</button>
<button class="right" data-dir="right" aria-label="Slide right"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><path d="M3 12h18m-8-8 8 8-8 8"/></svg>Right</button>
</div><div class="tools"><button id="undo" disabled>Undo</button><button id="hint">A little hint</button><button id="reset">Reset board</button></div></div>
<p class="tip" id="how-to">Tap an arrow, swipe the board, or focus it and use your arrow keys. No timer. Plenty of undo.</p>
<figure class="invention"><img src="data:image/webp;base64," width="900" height="600" alt="Concept illustration: a transparent CD-case lid taped to the side of a blue wired mouse with yellow tape."><figcaption><h3>Yes, this was a real idea.</h3><p>In 2007, Jon taped a CD-case lid to a mouse as a wide finger rest. This game borrows the transparent wing, then takes some liberties with the slipperiness.</p><small>Original generated illustration of the idea, not Jon's original photograph.</small></figcaption></figure>
</aside></div>
<section class="rules" aria-label="How the puzzle works"><div><h3>Think in stopping places.</h3><p>A nudge slides the mouse as far as it can go. Use the dark blocks and board edges to line up your next move. You must finish a slide on the yellow dock.</p><p>Stuck? Undo a move, reset the board, or ask for the next step on a shortest route from wherever you are.</p></div><div><h3>Dad versus Nathan?</h3><p>Take turns on the same board. See who finds the route with fewer nudges. Hints are allowed. Accusations of mouse sabotage are optional.</p><p>These are fictional sliding puzzles, not a simulation of the real device or an ergonomics test.</p></div></section>
<details><summary>Text map and accessible board description</summary><p>Rows run top to bottom; columns run left to right, both numbered 1 to 7. M is the mouse, G the goal, # a blocker, and . an empty square. The live message gives the position after each nudge. A hint tells you the next direction.</p><pre class="map" id="text-map" aria-label="Current board text map"></pre></details>
<footer>Inspired by Jon's <a href="?inspiration=1">GlassMouse: the do-it-yourself paper-thin mouse</a>. <a href="./">Back to the collection</a>.</footer>
<noscript><p>This sliding puzzle needs JavaScript. You can still read about the GlassMouse using the source link above.</p></noscript>
</main>
<script>
'use strict';
const levels=[{"name":"First slide","start":[0,6],"goal":[6,4],"walls":[[0,0],[0,4],[2,5],[3,0],[4,2],[5,1],[5,6],[6,6]]},{"name":"The long way round","start":[0,6],"goal":[3,2],"walls":[[0,5],[2,0],[2,1],[3,1],[3,3],[3,4],[4,2],[5,2],[6,3],[6,4]]},{"name":"Clear thinking","start":[0,6],"goal":[0,1],"walls":[[0,0],[0,4],[1,0],[1,1],[1,2],[2,1],[3,2],[3,5],[4,5],[5,0],[6,2],[6,4]]}];
const directions={up:[0,-1],right:[1,0],down:[0,1],left:[-1,0]};
const board=document.getElementById('board'), message=document.getElementById('message');
let levelIndex=0,position=[],history=[],trail=[],won=false,puck,walls;
const same=(a,b)=>a[0]===b[0]&&a[1]===b[1];
function endpoint(p,dir){const [dx,dy]=directions[dir];let [x,y]=p;while(x+dx>=0&&x+dx<7&&y+dy>=0&&y+dy<7&&!walls.has(`${x+dx},${y+dy}`)){x+=dx;y+=dy;}return [x,y];}
function pathFrom(start){const queue=[[start,[]]],seen=new Set([start.join(',')]);for(let i=0;i<queue.length;i++){const [p,path]=queue[i];if(same(p,levels[levelIndex].goal))return path;for(const dir of Object.keys(directions)){const dest=endpoint(p,dir),key=dest.join(',');if(!seen.has(key)){seen.add(key);queue.push([dest,[...path,dir]]);}}}return null;}
function legalDirections(){return Object.keys(directions).filter(d=>!same(endpoint(position,d),position));}
function update(){const step=100/7,gap=matchMedia('(max-width:760px)').matches?3:4;const size=(board.clientWidth-gap*6)/7;puck.style.left=`${position[0]*(size+gap)}px`;puck.style.top=`${position[1]*(size+gap)}px`;
 document.getElementById('moves').textContent=`${history.length} ${history.length===1?'move':'moves'}`;
 document.getElementById('undo').disabled=history.length===0||won;
 document.querySelectorAll('[data-dir]').forEach(b=>b.disabled=won);
 document.getElementById('hint').disabled=won;
 const state=`Mouse at row ${position[1]+1}, column ${position[0]+1}. Goal at row ${levels[levelIndex].goal[1]+1}, column ${levels[levelIndex].goal[0]+1}. ${won?'Docked.':'Open directions: '+legalDirections().join(', ')+'.'}`;
 document.getElementById('board-state').textContent=state;board.setAttribute('aria-label',`Board ${levelIndex+1}. ${state}`);
 let map='    1 2 3 4 5 6 7\n';for(let y=0;y<7;y++){map+=`${y+1}   `;for(let x=0;x<7;x++)map+=(same(position,[x,y])?'M':same(levels[levelIndex].goal,[x,y])?'G':walls.has(`${x},${y}`)?'#':'.')+' ';map+='\n';}document.getElementById('text-map').textContent=map;
 board.querySelectorAll('.cell').forEach((c,i)=>c.classList.toggle('trail',trail.some(p=>same(p,[i%7,Math.floor(i/7)]))));
}
function announce(text){message.textContent=text;}
function loadLevel(index,focus=false){levelIndex=index;position=[...levels[index].start];history=[];trail=[];won=false;walls=new Set(levels[index].walls.map(p=>p.join(',')));board.replaceChildren();
 for(let y=0;y<7;y++)for(let x=0;x<7;x++){const c=document.createElement('div');c.className='cell'+(walls.has(`${x},${y}`)?' wall':'')+(same([x,y],levels[index].goal)?' goal':'');c.setAttribute('aria-hidden','true');if(same([x,y],levels[index].goal))c.textContent='DOCK';board.append(c);}
 puck=document.createElement('div');puck.className='puck';puck.setAttribute('aria-hidden','true');puck.innerHTML='<svg viewBox="0 0 64 64" fill="none"><rect x="3" y="14" width="42" height="42" rx="3" fill="#ffffff88" stroke="#102851" stroke-width="2"/><rect x="7" y="18" width="34" height="34" rx="1" stroke="#ffffff" stroke-width="2"/><path d="M17 28v17l5-5 5 9 4-2-5-9h7z" fill="#102851"/><rect x="42" y="11" width="18" height="43" rx="9" fill="#164bcc" stroke="#102851" stroke-width="2"/><path d="M51 12v17m-8 1h16" stroke="white" stroke-width="1.5"/><rect x="37" y="19" width="9" height="9" fill="#fff16a" stroke="#102851"/><rect x="37" y="39" width="9" height="9" fill="#fff16a" stroke="#102851"/></svg>';board.append(puck);
 document.getElementById('level-title').textContent=levels[index].name;document.getElementById('objective').textContent=`Board ${index+1} of 3 · Stop on the dock. Passing over it doesn't count.`;
 document.querySelectorAll('.progress span').forEach((s,i)=>{s.className=i===index?'current':i<index?'passed':'';if(i===index)s.setAttribute('aria-current','step');else s.removeAttribute('aria-current');});
 document.getElementById('success').hidden=true;document.getElementById('next').hidden=true;announce('Take a nudge. The mouse stops at the next blocker or edge.');update();if(focus)board.focus({preventScroll:true});
}
function move(dir){if(won)return;const dest=endpoint(position,dir);if(same(dest,position)){announce(`Blocked ${dir}. Try ${legalDirections().join(' or ')}. No move used.`);return;}history.push({position:[...position],trail:trail.map(p=>[...p])});const [dx,dy]=directions[dir];let [x,y]=position;while(x!==dest[0]||y!==dest[1]){trail.push([x,y]);x+=dx;y+=dy;}position=dest;won=same(position,levels[levelIndex].goal);update();if(won){const shortest=pathFrom(levels[levelIndex].start).length;const final=levelIndex===levels.length-1;document.getElementById('success').hidden=false;document.getElementById('success-title').textContent=final?'All three docked!':'Perfect landing.';announce(`${history.length} moves. A shortest route takes ${shortest}. ${history.length===shortest?'You found it!':'A few scenic detours never hurt.'}${final?' Your CD case has earned its desk space.':''}`);const next=document.getElementById('next');next.hidden=false;next.textContent=final?'Play again':'Next board';document.getElementById('success-title').focus({preventScroll:true});}else announce(`Slid ${dir}. Row ${position[1]+1}, column ${position[0]+1}. Open directions: ${legalDirections().join(', ')}.`);}
 document.querySelectorAll('[data-dir]').forEach(b=>b.addEventListener('click',()=>move(b.dataset.dir)));
 document.getElementById('undo').addEventListener('click',()=>{if(!history.length||won)return;const previous=history.pop();position=previous.position;trail=previous.trail;update();announce(`Undone. Row ${position[1]+1}, column ${position[0]+1}.`);if(document.getElementById('undo').disabled)board.focus({preventScroll:true});});
 document.getElementById('reset').addEventListener('click',()=>loadLevel(levelIndex,true));
 document.getElementById('hint').addEventListener('click',()=>{const path=pathFrom(position);announce(path?.length?`Try ${path[0]}. A shortest route from here takes ${path.length} ${path.length===1?'nudge':'nudges'}.`:'No route from here. Undo a move or reset the board.');});
 document.getElementById('next').addEventListener('click',()=>loadLevel((levelIndex+1)%levels.length,true));
 document.addEventListener('keydown',e=>{const dir={ArrowUp:'up',ArrowRight:'right',ArrowDown:'down',ArrowLeft:'left'}[e.key];if(dir&&(document.activeElement===board||document.activeElement?.matches('[data-dir]'))){e.preventDefault();move(dir);}});
 let touchStart=null;board.addEventListener('pointerdown',e=>{if(e.isPrimary){touchStart=[e.clientX,e.clientY,e.pointerId];board.setPointerCapture(e.pointerId);board.focus({preventScroll:true});}});board.addEventListener('pointerup',e=>{if(!touchStart||e.pointerId!==touchStart[2])return;const dx=e.clientX-touchStart[0],dy=e.clientY-touchStart[1];touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))<16)return;move(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up');});board.addEventListener('pointercancel',()=>touchStart=null);
 new ResizeObserver(()=>{if(puck)update();}).observe(board);loadLevel(0);
</script>
</body></html>
